//! Parity with the TypeScript engine: every case of `engines/fixtures/conflict-risk.json`
//! (generated by `engines/fixtures/conflict-risk.ts`) must produce the same bytes, and every
//! request TypeScript cannot answer must be refused.

#![allow(clippy::panic)] // a test harness reports fixture problems by panicking

use serde_json::{Map, Value};
use sipges_analytics_common::js;
use sipges_conflict_risk::{EngineError, run};

fn fixtures() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/conflict-risk.json"
    );
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("parse {path}: {e}"))
}

fn str_of<'a>(v: &'a Value, key: &str) -> &'a str {
    v.get(key)
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("fixture field {key} must be a string"))
}

fn array<'a>(v: &'a Value, key: &str) -> &'a [Value] {
    v.get(key)
        .and_then(Value::as_array)
        .unwrap_or_else(|| panic!("fixture field {key} must be an array"))
}

fn request(text: &str) -> Map<String, Value> {
    serde_json::from_str(text).unwrap_or_else(|e| panic!("request {text}: {e}"))
}

#[test]
fn every_case_matches_the_typescript_engine_byte_for_byte() {
    let fixtures = fixtures();
    let cases = array(&fixtures, "cases");
    assert!(cases.len() >= 25, "expected the full fixture set");
    let mut failures = Vec::new();
    for case in cases {
        let name = str_of(case, "name");
        match run(&request(str_of(case, "request"))) {
            Ok(value) => {
                let actual = js::stringify(&value);
                let expected = str_of(case, "value");
                if actual != expected {
                    let at = actual
                        .bytes()
                        .zip(expected.bytes())
                        .position(|(a, b)| a != b)
                        .unwrap_or(actual.len().min(expected.len()));
                    let from = at.saturating_sub(150);
                    failures.push(format!(
                        "{name} (first difference at byte {at}):\n  expected …{}\n  actual   …{}",
                        expected
                            .get(from..(at + 150).min(expected.len()))
                            .unwrap_or(""),
                        actual.get(from..(at + 150).min(actual.len())).unwrap_or("")
                    ));
                }
            }
            Err(e) => failures.push(format!("{name}: {e}")),
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn requests_typescript_cannot_answer_are_refused() {
    let fixtures = fixtures();
    let errors = array(&fixtures, "errors");
    assert!(!errors.is_empty());
    for case in errors {
        let name = str_of(case, "name");
        let got = run(&request(str_of(case, "request")));
        assert_eq!(
            got.as_ref().err().map(EngineError::code),
            Some("unsupported_value"),
            "{name}: {got:?}"
        );
    }
}

fn code(text: &str) -> Option<&'static str> {
    run(&request(text)).err().map(|e| e.code())
}

#[test]
fn rejects_shapes_the_typescript_types_reject() {
    let ok = r#""alerts":[],"irsa":[],"today":"2026-11-02""#;
    let rec = |fields: &str| format!(r#"{{"records":[{{{fields}}}],{ok}}}"#);
    let alert = |fields: &str| {
        format!(r#"{{"records":[],"alerts":[{{{fields}}}],"irsa":[],"today":"2026-11-02"}}"#)
    };
    let good_alert = r#""id":"a","createdAt":"2026-11-01","territory":null,"level":"Alta","status":"Nueva","reviewedAt":null"#;
    for bad in [
        r#"{"alerts":[],"irsa":[],"today":"2026-11-02"}"#.to_owned(),
        r#"{"records":null,"alerts":[],"irsa":[],"today":"2026-11-02"}"#.to_owned(),
        r#"{"records":{},"alerts":[],"irsa":[],"today":"2026-11-02"}"#.to_owned(),
        r#"{"records":[],"irsa":[],"today":"2026-11-02"}"#.to_owned(),
        r#"{"records":[],"alerts":[],"today":"2026-11-02"}"#.to_owned(),
        r#"{"records":[],"alerts":[],"irsa":[]}"#.to_owned(),
        r#"{"records":[],"alerts":[],"irsa":[],"today":20261102}"#.to_owned(),
        r#"{"records":[],"alerts":[],"irsa":[],"today":"2026-1-02"}"#.to_owned(),
        r#"{"records":[],"alerts":[],"irsa":[],"today":"2026-11-32"}"#.to_owned(),
        r#"{"records":[],"alerts":[],"irsa":[],"today":"2026-13-01"}"#.to_owned(),
        r#"{"records":[],"alerts":[],"irsa":[],"today":"2026-11-02T00:00:00Z"}"#.to_owned(),
        rec(r#""id":"r","payload":{},"updatedAt":null"#),
        rec(r#""module":1,"id":"r","payload":{},"updatedAt":null"#),
        rec(r#""module":"Demandas","id":1,"payload":{},"updatedAt":null"#),
        rec(r#""module":"Demandas","id":"r","payload":[],"updatedAt":null"#),
        rec(r#""module":"Demandas","id":"r","payload":null,"updatedAt":null"#),
        rec(r#""module":"Demandas","id":"r","payload":{}"#),
        rec(r#""module":"Demandas","id":"r","payload":{},"updatedAt":1"#),
        format!(r#"{{"records":[1],{ok}}}"#),
        alert(r#""createdAt":"2026-11-01","territory":null,"level":"Alta","status":"Nueva","reviewedAt":null"#),
        alert(r#""id":"a","createdAt":null,"territory":null,"level":"Alta","status":"Nueva","reviewedAt":null"#),
        alert(r#""id":"a","createdAt":"2026-11-01","level":"Alta","status":"Nueva","reviewedAt":null"#),
        alert(r#""id":"a","createdAt":"2026-11-01","territory":1,"level":"Alta","status":"Nueva","reviewedAt":null"#),
        alert(r#""id":"a","createdAt":"2026-11-01","territory":null,"level":null,"status":"Nueva","reviewedAt":null"#),
        alert(r#""id":"a","createdAt":"2026-11-01","territory":null,"level":"Alta","status":1,"reviewedAt":null"#),
        alert(r#""id":"a","createdAt":"2026-11-01","territory":null,"level":"Alta","status":"Nueva""#),
        r#"{"records":[],"alerts":[],"irsa":[{"ts":"2026-11-01"}],"today":"2026-11-02"}"#.to_owned(),
        r#"{"records":[],"alerts":[],"irsa":[{"ts":1,"irsa":2}],"today":"2026-11-02"}"#.to_owned(),
        r#"{"records":[],"alerts":[],"irsa":[{"ts":"2026-11-01","irsa":"2"}],"today":"2026-11-02"}"#.to_owned(),
        r#"{"records":[],"alerts":[],"irsa":[null],"today":"2026-11-02"}"#.to_owned(),
    ] {
        assert_eq!(code(&bad), Some("invalid_input"), "{bad}");
    }
    assert!(code(&alert(good_alert)).is_none());
    assert!(
        code(&rec(
            r#""module":"Demandas","id":"r","payload":{},"updatedAt":"x""#
        ))
        .is_none()
    );
}
